
$(document).ready(function(){$('#UserName').focus();document.forms[0].onsubmit=function(){if($('#UserName').val()==''){$('#UserName').focus();Validators.show($('#UserName').get(0),'This field is required');Validators.animate($('#UserName').get(0));return false;}
if($('#Password').val()==''){$('#Password').focus();Validators.show($('#Password').get(0),'This field is required');Validators.animate($('#Password').get(0));return false;}};});